document.addEventListener('submit',async ev=>{const f=ev.target;if(f.id!=='asg-form'||!isStaff())return;ev.preventDefault();
  try{const d=Object.fromEntries(new FormData(f));if(f.dataset.id)d.id=Number(f.dataset.id);const prev=d.id?ASSIGN.find(x=>x.id===d.id):null;asgPack(d,prev?asgClosed(prev):false);await api('/api/assignments',{method:'POST',json:d});ASSIGN=await api('/api/assignments',{cache:'no-store'});asgSig=JSON.stringify(ASSIGN);state.editAsg=null;render();notice(d.id?'Assignment updated.':'Assignment published. Participants can see it now.')}catch(err){notice(String(err))}});


/* ================= v25 additions =================
   1. Assignments: Close / Reopen / Delete, live sync (no refresh needed)
   2. Attendance: full e-mail always visible, Excel (.xlsx) export with auto-fit columns
   ================================================= */
(function(){const s=document.createElement('style');s.textContent=`
.tbl td.em{white-space:nowrap;overflow-wrap:normal;word-break:keep-all;min-width:240px}
.tbl td,.tbl th{max-width:none}
.pill.closed,.closed-pill{background:#fbe3e1;color:#b3372f;font-size:11px;font-weight:700;border-radius:99px;padding:3px 10px;display:inline-block}
.pill.open-p{background:#dff3e7;color:#1b7a43}
.asg-card.is-closed{opacity:.72;background:#f7f9fb}
.asg-card.is-closed h3{text-decoration:none;color:var(--muted)}
.live-dot{display:inline-flex;align-items:center;gap:6px;font-size:11px;color:#1b7a43;font-weight:700}
.live-dot::before{content:"";width:8px;height:8px;border-radius:50%;background:currentColor}
`;document.head.appendChild(s)})();

const ASG_TOKEN='[[CLOSED]]';
function asgClosed(a){return !!a&&(a.closed===true||a.closed===1||a.closed==='1'||a.closed==='true'||String(a.instructions||'').trimStart().startsWith(ASG_TOKEN))}
function asgText(a){return String((a&&a.instructions)||'').replace(/^\s*\[\[CLOSED\]\]\s*/,'')}
function asgPack(d,closed){d.closed=closed?1:0;d.instructions=(closed?ASG_TOKEN+'\n':'')+asgText({instructions:d.instructions});return d}
function asgDeadlineMs(a){if(!a||!a.deadline)return NaN;const s=String(a.deadline).trim();if(/[zZ]$|[+-]\d\d:?\d\d$/.test(s)&&s.length>16)return Date.parse(s);return Date.parse((s.length===16?s+':00':s.replace(' ','T'))+'+05:30')}
function asgOverdue(a){const t=asgDeadlineMs(a);return !isNaN(t)&&Date.now()>t}
let asgSig=JSON.stringify(ASSIGN);

function asgList(){
  const open=ASSIGN.filter(a=>!asgClosed(a)),closed=ASSIGN.filter(asgClosed);
  const card=(a,i)=>{const c=asgClosed(a),od=!c&&asgOverdue(a),txt=asgText(a),url=a.form_url&&safeURL(a.form_url)!=='#'?safeURL(a.form_url):'';
    return `<article class="panel asg-card ${c?'is-closed':''}" style="margin-bottom:14px"><span class="pill ${c?'closed':'open-p'}">${c?'CLOSED':(i===0?'LATEST · OPEN':'OPEN')}</span> ${od?'<span class="warn-pill">Deadline passed</span> ':''}<span class="fine">${e(a.day||'Course-wide')}${a.deadline?' · Deadline: '+e(String(a.deadline).replace('T',' '))+' IST':''}</span><h3 style="margin-top:12px">${e(a.title)}</h3>${txt?`<p class="prewrap" style="font-size:14px">${e(txt)}</p>`:''}<div class="actions">${c?'<span class="fine">Submissions are closed for this assignment.</span>':(url?`<a class="button" href="${e(url)}" target="_blank" rel="noopener noreferrer">Open Google Form ↗</a>`:'<span class="fine">Form link will be added soon.</span>')}${isStaff()?button('asg-edit','Edit',`data-id="${a.id}"`,'button secondary small')+(c?button('asg-reopen','Reopen',`data-id="${a.id}"`,'button secondary small'):button('asg-close','Close',`data-id="${a.id}"`,'button secondary small'))+button('asg-del','Delete',`data-id="${a.id}"`,'button secondary small danger'):''}</div></article>`};
  if(!ASSIGN.length)return '<div class="empty">No assignment has been published yet. It will appear here as soon as the faculty publish it.</div>';
  return (open.length?open.map(card).join(''):'<div class="empty">No open assignment right now.</div>')
    +(closed.length?`<div class="section-heading" style="margin-top:26px"><h2>Closed assignments</h2>${isStaff()?button('asg-del-closed','Delete all closed','','button secondary small danger'):''}</div>`+closed.map(card).join(''):'');
}
function assignBoard(){
  const edit=ASSIGN.find(a=>a.id===state.editAsg);
  const form=isStaff()?`<section class="panel" style="margin-bottom:18px"><span class="overline">${isAdmin()?'ADMIN':'FACULTY'} · PUBLISH</span><h2>${edit?'Edit assignment':'Publish a new assignment'}</h2><p class="muted" style="font-size:13px">Add the assignment with its Google Form link. Participants see it within seconds, without refreshing. When a day's task is finished, press <b>Close</b> (hides the form link, can be reopened) or <b>Delete</b> (removes it completely).</p><form id="asg-form" class="assignment-form" data-id="${edit?edit.id:''}"><label>Title<input name="title" required maxlength="160" value="${e(edit?edit.title:'')}" placeholder="e.g. Day 2 · Rights matrix"></label><div class="form-row"><label>For<select name="day"><option>Course-wide</option>${[1,2,3,4,5,6,7].map(n=>`<option ${edit&&edit.day==='Day '+n?'selected':''}>Day ${n}</option>`).join('')}</select></label><label>Deadline (IST)<input name="deadline" type="datetime-local" value="${e(edit?edit.deadline:'')}"></label></div><label>Instructions<textarea name="instructions" rows="4" maxlength="4000" placeholder="What should participants submit?">${e(edit?asgText(edit):'')}</textarea></label><label>Google Form link<input name="form_url" type="url" placeholder="https://forms.gle/…" value="${e(edit?edit.form_url:'')}"></label><div class="actions"><button class="button" type="submit">${edit?'Save changes':'Publish assignment'}</button>${edit?button('asg-cancel','Cancel','type="button"'):''}</div></form></section>`:'';
  return `<div class="section-heading"><h2>Published assignments</h2><span class="live-dot">Live · updates automatically</span></div>${form}<div id="asg-list">${asgList()}</div>`}

/* close / reopen / delete-all-closed */
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||!isStaff())return;const a=el.dataset.action;
  if(a!=='asg-close'&&a!=='asg-reopen'&&a!=='asg-del-closed')return;
  try{
    if(a==='asg-del-closed'){const cl=ASSIGN.filter(asgClosed);if(!cl.length)return;if(!confirm('Permanently delete all '+cl.length+' closed assignment(s)?'))return;
      for(const x of cl)await api('/api/assignments/'+x.id,{method:'DELETE'});
      ASSIGN=await api('/api/assignments',{cache:'no-store'});asgSig=JSON.stringify(ASSIGN);render();notice('Closed assignments deleted.');return}
    const x=ASSIGN.find(z=>z.id===Number(el.dataset.id));if(!x)return;const close=a==='asg-close';
    if(close&&!confirm('Close this assignment? Participants will no longer see its Google Form link. You can reopen it any time.'))return;
    const d={id:x.id,title:x.title,day:x.day,deadline:x.deadline,form_url:x.form_url,instructions:asgText(x)};asgPack(d,close);
    await api('/api/assignments',{method:'POST',json:d});
    ASSIGN=await api('/api/assignments',{cache:'no-store'});asgSig=JSON.stringify(ASSIGN);render();notice(close?'Assignment closed.':'Assignment reopened.');
  }catch(err){notice(String(err))}});

/* live sync: everyone sees new / closed / deleted assignments without refreshing */
let asgBusy=false,asgLast=0;
async function asgSync(force){
  if(!user||asgBusy||(document.hidden&&!force))return;asgBusy=true;
  try{const n=await api('/api/assignments',{cache:'no-store'});if(!Array.isArray(n))return;const sig=JSON.stringify(n);if(sig===asgSig)return;
    const oldIds=new Set(ASSIGN.map(x=>x.id)),fresh=n.filter(x=>!oldIds.has(x.id)&&!asgClosed(x));
    asgSig=sig;ASSIGN=n;
    if(state.view==='assignments'){
      const typing=document.activeElement&&document.activeElement.closest&&document.activeElement.closest('#asg-form,#formurl-form');
      if(isStaff()&&typing){const l=$('asg-list');if(l)l.innerHTML=asgList()}else render();
    }
    if(!isStaff()&&fresh.length)notice('New assignment: '+fresh[0].title);
  }catch(_){}finally{asgBusy=false;asgLast=Date.now()}}
setInterval(()=>asgSync(false),10000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)asgSync(true)});
addEventListener('online',()=>asgSync(true));
{const _render=render;render=function(){_render();if(state.view==='assignments'&&Date.now()-asgLast>3000){asgLast=Date.now();asgSync(true)}}}

/* ---------- Excel (.xlsx) export, no library needed ---------- */
const _crcT=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
const _crc=b=>{let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=_crcT[(c^b[i])&255]^(c>>>8);return(c^0xFFFFFFFF)>>>0};
function zipStore(files){const enc=new TextEncoder(),parts=[],cd=[];let off=0;
  const u16=n=>[n&255,(n>>>8)&255],u32=n=>[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255];
  for(const [name,text] of files){const nb=enc.encode(name),db=enc.encode(text),crc=_crc(db);
    const lh=new Uint8Array([0x50,0x4b,3,4,...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0x21),...u32(crc),...u32(db.length),...u32(db.length),...u16(nb.length),...u16(0)]);
    parts.push(lh,nb,db);
    cd.push(new Uint8Array([0x50,0x4b,1,2,...u16(20),...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0x21),...u32(crc),...u32(db.length),...u32(db.length),...u16(nb.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(off)]),nb);
    off+=lh.length+nb.length+db.length}
  let cdLen=0;cd.forEach(x=>cdLen+=x.length);
  const end=new Uint8Array([0x50,0x4b,5,6,...u16(0),...u16(0),...u16(files.length),...u16(files.length),...u32(cdLen),...u32(off),...u16(0)]);
  return new Blob([...parts,...cd,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function xlsxBlob(rows,opts={}){
  const X=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'');
  const col=i=>{let s='';i++;while(i>0){const m=(i-1)%26;s=String.fromCharCode(65+m)+s;i=Math.floor((i-1)/26)}return s};
  const nCols=Math.max(...rows.map(r=>r.length));const w=Array(nCols).fill(8);
  rows.forEach(r=>r.forEach((v,i)=>{const l=String(v??'').length;if(l>w[i])w[i]=l}));
  const cols=w.map((x,i)=>`<col min="${i+1}" max="${i+1}" width="${Math.min(Math.max(x+3,i>=(opts.centerFrom??99)?8:10),70)}" customWidth="1"/>`).join('');
  const sheet=rows.map((r,ri)=>`<row r="${ri+1}">`+r.map((v,ci)=>{const ref=col(ci)+(ri+1),st=ri===0?1:(ci>=(opts.centerFrom??99)?2:0);
    return typeof v==='number'&&isFinite(v)?`<c r="${ref}" s="${st}"><v>${v}</v></c>`:`<c r="${ref}" s="${st}" t="inlineStr"><is><t xml:space="preserve">${X(v)}</t></is></c>`}).join('')+'</row>').join('');
  const files=[
   ['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'],
   ['_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
   ['xl/workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="'+X(opts.sheet||'Attendance')+'" sheetId="1" r:id="rId1"/></sheets></workbook>'],
   ['xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'],
   ['xl/styles.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF224B82"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'],
   ['xl/worksheets/sheet1.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>'+cols+'</cols><sheetData>'+sheet+'</sheetData></worksheet>']];
  return zipStore(files)}

/* report -> Excel (full email visible, columns auto-fitted) */
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action="rep-xlsx"]');if(!el)return;
  const d=REP;if(!d||!d.rows){notice('Report is still loading.');return}
  const cell=repCell;
  const rows=[['Name','Email','Days present',...d.days],...d.rows.map(r=>[r.name,r.email,r.present,...d.days.map(x=>cell(r.marks[x]))])];
  download0('attendance.xlsx',xlsxBlob(rows,{sheet:'Attendance',centerFrom:2}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  notice('Excel file downloaded.')});

/* ---- attendance report: earliest check-in on top, late ones below, absent last ---- */
function repTime(v){const m=/(\d{1,2}):(\d{2})/.exec(typeof v==='string'?v:'');return m?(+m[1])*60+(+m[2]):null}
function repCell(m){return m?(typeof m==='string'&&m!=='true'&&m!=='1'?(/^P\b/i.test(m)?m:'P '+m):'P'):'A'}
function repSort(d){const last=(d.days||[])[(d.days||[]).length-1];
  const rank=r=>{const v=r.marks&&r.marks[last];if(!v)return [2,0];const t=repTime(v);return t==null?[1,0]:[0,t]};
  return (d.rows||[]).map((r,i)=>({r,i,k:rank(r)})).sort((a,b)=>a.k[0]-b.k[0]||a.k[1]-b.k[1]||a.i-b.i).map(x=>x.r)}
